15	export function countEOL(text: string): [number, number, number, StringEOL] {
16		let eolCount = 0;
17		let firstLineLength = 0;
18		let lastLineStart = 0;
19		let eol: StringEOL = StringEOL.Unknown;
20		for (let i = 0, len = text.length; i < len; i++) {
21			const chr = text.charCodeAt(i);
22	
23			if (chr === CharCode.CarriageReturn) {
24				if (eolCount === 0) {
25					firstLineLength = i;
26				}
27				eolCount++;
28				if (i + 1 < len && text.charCodeAt(i + 1) === CharCode.LineFeed) {
29					// \r\n... case
30					eol |= StringEOL.CRLF;
31					i++; // skip \n
32				} else {
33					// \r... case
34					eol |= StringEOL.Invalid;
35				}
36				lastLineStart = i + 1;
37			} else if (chr === CharCode.LineFeed) {
38				// \n... case
39				eol |= StringEOL.LF;
40				if (eolCount === 0) {
41					firstLineLength = i;
42				}
43				eolCount++;
44				lastLineStart = i + 1;
45			}
46		}
47		if (eolCount === 0) {
48			firstLineLength = text.length;
49		}
50		return [eolCount, firstLineLength, text.length - lastLineStart, eol];
51	}
